import{_ as e,z as t,m as a,ap as l}from"./chunks/framework.bQJNM8pB.js";const i="/adapter-yunhupro/assets/2025-10-24_15-43-37.COPgmC4w.png",r="/adapter-yunhupro/assets/495cb157-5c28-4837-b736-40982172dd44.CTN8oxdI.png",k=JSON.parse('{"title":"Webhook 方式接入教程","description":"","frontmatter":{},"headers":[],"relativePath":"markdown/firstime/start-webhook.md","filePath":"markdown/firstime/start-webhook.md","lastUpdated":1786201283000}'),s={name:"markdown/firstime/start-webhook.md"};function n(h,o,c,d,p,u){return a(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="webhook-方式接入教程" tabindex="-1">Webhook 方式接入教程 <a class="header-anchor" href="#webhook-方式接入教程" aria-label="Permalink to &quot;Webhook 方式接入教程&quot;">​</a></h1><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>本教程适用于选择 <strong>Webhook 方式</strong> 接入的用户。</p><p>通过 Webhook 接收事件推送，<strong>需要公网访问能力</strong>。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>选择此方式前，请务必确认您满足以下<strong>条件之一</strong>：</p><ul><li>拥有一个公网 IPv4 或 IPv6 地址。</li><li>使用内网穿透服务（如 frp, Ngrok, Cloudflare Tunnel 等）将您的本地 Koishi 服务暴露到公网。</li></ul></div><blockquote><p><strong>前置准备</strong>：请先完成 <a href="./start.html">首次接入指南</a> 中的公共步骤（创建机器人、获取 Token、配置订阅事件）。</p></blockquote><h2 id="_1-配置-webhook-方式" tabindex="-1">1. 配置 Webhook 方式 <a class="header-anchor" href="#_1-配置-webhook-方式" aria-label="Permalink to &quot;1. 配置 Webhook 方式&quot;">​</a></h2><p>在 Koishi 的插件市场中找到并安装 <code>adapter-yunhupro</code> 适配器，然后进入配置页面。</p><ol><li><strong>Token</strong>：填入在首次接入指南中获取的机器人 Token</li><li><strong>订阅方式</strong>：选择 <code>webhook</code></li><li><strong>本机监听路径</strong>：默认为 <code>/yunhu</code>，您可以自定义</li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>关于监听路径的重要说明</strong></p><p>如果您需要运行多个云湖机器人实例，请为每个实例配置<strong>不同的监听路径</strong>。</p><p>例如：</p><ul><li>机器人 A：<code>/yunhu1</code></li><li>机器人 B：<code>/yunhu2</code></li></ul><p>使用相同的路径会导致消息混乱！</p></div><p>保存配置，使适配器开始监听本地路径。</p><h2 id="_2-配置订阅地址" tabindex="-1">2. 配置订阅地址 <a class="header-anchor" href="#_2-配置订阅地址" aria-label="Permalink to &quot;2. 配置订阅地址&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>注意：此步骤务必使用<strong>公网地址</strong>访问！</p></div><ol><li><strong>确认订阅地址</strong>：将您的 Koishi 公网访问地址与配置的 <code>path</code> 组合成完整的 Webhook URL。 <ul><li>例如，如果您的公网域名是 <code>https://your.domain.com</code>，并且 <code>path</code> 配置为 <code>/yunhu</code>，那么完整的订阅地址就是 <code>https://your.domain.com/yunhu</code>。</li></ul></li><li><strong>打开浏览器访问订阅地址</strong>： <ul><li>如果你可以访问看到 <code>适配器已成功启动</code> 页面，则说明配置成功！</li></ul></li></ol><p><img src="'+i+'" alt="适配器已成功启动"></p><h2 id="_3-在云湖后台配置-webhook" tabindex="-1">3. 在云湖后台配置 Webhook <a class="header-anchor" href="#_3-在云湖后台配置-webhook" aria-label="Permalink to &quot;3. 在云湖后台配置 Webhook&quot;">​</a></h2><p>回到云湖平台的机器人后台，进行以下配置：</p><ol><li><p><strong>配置订阅地址</strong>：填入您的完整订阅地址，例如 <code>https://your.domain.com/yunhu</code>。</p></li><li><p><strong>订阅事件</strong>：根据您的需求，勾选需要接收的事件类型。</p><ul><li>为了确保机器人能正常响应消息，<strong>「消息事件」</strong> 是必须订阅的。</li></ul></li></ol><p><img src="'+r+'" alt="配置订阅地址和事件"></p><h2 id="_4-测试连接" tabindex="-1">4. 测试连接 <a class="header-anchor" href="#_4-测试连接" aria-label="Permalink to &quot;4. 测试连接&quot;">​</a></h2><p>完成以上所有配置后，您可以对机器人进行一次简单的测试，以验证连接是否成功。</p><ul><li><strong>私聊</strong> 您的机器人，发送任意消息，例如 <code>status</code>。</li><li>如果您的 Koishi 机器人做出了回应，说明连接已经成功建立。</li></ul><h2 id="_5-webhook-方式排查" tabindex="-1">5. Webhook 方式排查 <a class="header-anchor" href="#_5-webhook-方式排查" aria-label="Permalink to &quot;5. Webhook 方式排查&quot;">​</a></h2><p>如果机器人没有响应，请检查以下几点：</p><ul><li>Koishi 服务是否正常运行？</li><li>公网地址和 Webhook 路径是否正确？</li><li>云湖后台的事件订阅是否已开启？</li><li>检查 Koishi 的控制台日志，确认是否有来自云湖的请求或任何错误信息。</li></ul><h2 id="多机器人配置-webhook" tabindex="-1">多机器人配置（Webhook） <a class="header-anchor" href="#多机器人配置-webhook" aria-label="Permalink to &quot;多机器人配置（Webhook）&quot;">​</a></h2><p>如果您需要运行多个云湖机器人，请使用 Koishi 的<strong>多开插件功能</strong>：</p><ol><li>在插件列表中找到 <code>adapter-yunhupro</code></li><li>点击「添加实例」按钮</li><li>为每个实例配置不同的 Token</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Webhook 方式</strong>：每个实例必须配置不同的监听路径</p></div>',29)])])}const g=e(s,[["render",n]]);export{k as __pageData,g as default};
